'use strict';

// MODULES //

import covariance from '@stdlib/stats-incr-covariance';
import isnan from '@stdlib/math-base-assert-is-nan';


// MAIN //

/**
* Returns an accumulator function which incrementally computes a sample covariance, ignoring `NaN` values.
*
* @returns {Function} accumulator function
*
* @example
* import incrnancovariance from '@stdlib/stats-incr-nancovariance';
*
* var acc = incrnancovariance();
*
* var cov = acc();
* // returns null
*
* cov = acc( 2.0, 1.0 );
* // returns null
*
* cov = acc( NaN, 5.0 );
* // returns null
*
* cov = acc( 4.0, 5.0 );
* // returns 4.0
*
* cov = acc();
* // returns 4.0
*/
function incrnancovariance() {
	var count = 0;
	var acc = covariance();
	return accumulator;

	/**
	* Updates and returns the sample covariance when provided two numeric arguments.
	* If no arguments are provided, returns the current sample covariance.
	*
	* @private
	* @param {number} [x] - new x value
	* @param {number} [y] - new y value
	* @returns {(number|null)} sample covariance or null
	*/
	function accumulator( x, y ) {
		var val;
		if ( arguments.length === 0 ) {
			return ( count < 2 ) ? null : acc();
		}
		if ( isnan( x ) || isnan( y ) ) {
			return ( count < 2 ) ? null : acc();
		}
		count += 1;
		val = acc( x, y );
		return ( count < 2 ) ? null : val;
	}
}


// EXPORTS //

export default incrnancovariance;
